data/planes/unlit/plane.kyr:
Module unlit "The Unlit" {
  Description "The cellar of the world, where the Lamplighters laid down their light: a country of ash under no sky, where nothing shines but what is carried in and fire burns small and cold. Their beacons stood at its doors. The last of their wardens is dead and not gone, and still counts what he kept when the doors were shut.".
  Entity party: group "Your company".
  // Where its doors open in the Varrow, and the Unlight whose going showed the first of them.
  Place deep_cellar "The Lanthorn's deep cellar" is room.
  Place far_shore "The far shore of the still lake" is room.
  Entity unlight: scenery "The Unlight". Entity unlight_gone: condition "gone".

  Place unlit "the Unlit" is plane.
  Place cellarlands "the Cellarlands" is region within unlit.
  Place ash "the Ash" is wilderness within cellarlands at 0, 0.
  Place lampfall "Lampfall" is site within cellarlands at 1, 0.
  Place lampfall_court "the outer court" is level within lampfall.
  Place lampfall_keep "the keep" is level within lampfall.
  Place lampfall_tower "the beacon tower" is level within lampfall.
  Place veil_foot "the foot of the veil" is room within ash at 0, 1.
  Place ash_road "the ash road" is room within ash at 1, 1.
  Place cinders "the cinder hollow" is room within ash at 1, 2.
  Place mere_edge "the edge of the Ash Mere" is room within ash at 2, 2.
  Place drowned_stair "the head of the drowned stair" is room within ash at 3, 2.
  Place arch "the Arch of Ways" is room within ash at 2, 0.
  Place lamp_door "the Lamplighters' door" is room within ash at 3, 0.
  Place gate_ward "the gate ward of Lampfall" is room within lampfall_court at 0, 0.
  Place ledger_hall "the ledger hall" is room within lampfall_keep at 0, 0.
  Place jar_vault "the jar vault" is room within lampfall_keep at 1, 0.
  Place beacon_room "the beacon room" is room within lampfall_tower at 0, 0.
  Initially Assert law(unlit, unlit_law). Entity unlit_law: law "the Unlit's law". Entity beacon_law: law "under the beacon".
  Initially Assert lightless(veil_foot). Initially Assert lightless(ash_road). Initially Assert lightless(cinders).
  Initially Assert lightless(mere_edge). Initially Assert lightless(drowned_stair). Initially Assert lightless(arch).
  Initially Assert lightless(lamp_door). Initially Assert lightless(gate_ward). Initially Assert lightless(ledger_hall).
  Initially Assert lightless(jar_vault). Initially Assert lightless(beacon_room).

  // The veil: under the scorch the Unlight left, the floor of the deep cellar is thin. It cannot be seen until the
  // Unlight is gone, and cannot be passed without sunlight to see by on the other side.
  Discovery veil_known "Where the Unlight was, the deep cellar's floor is thin as a curtain: there is somewhere else under it, and the Lamplighters' writing on the walls is a warning about what." {
    Found by searching deep_cellar "Where the scorch is, the floor gives under your hand like cloth, and through it comes a cold that has never been warm.".
  }
  Passage veil "the veil under the deep cellar" is portal between deep_cellar and veil_foot taking 1 hour hidden until veil_known needing sunlight.
  Thing unlight_stain "the dark over the veil" on veil {
    State filled blocking "The Unlight sits on the place where the floor is thin.".
    State clear "Nothing sits over the scorch now.".
  }
  Rule veil_clears when state(unlight, unlight_gone) and state(unlight_stain, filled) { Assert state(unlight_stain, clear). }
  // The drowned stair: the Lamplighters' other door, under the still lake, found from either side by looking hard.
  Discovery mere_way_known "Under the still lake a stair goes down, and on down, out of the water and into the Unlit: the Lamplighters' back door, which the Glimmerkin's boatmen will not pole over." {
    Found by searching far_shore "Where the jars lie smashed, steps go down into the lake, cut in the rock, and the water over them is not as deep as it is black.".
    Found by searching drowned_stair "The stair goes on up into still black water, and very far up there is a little green light, a Glimmerkin jar.".
  }
  Passage drowned_way "the drowned stair" is portal between far_shore and drowned_stair taking 2 hours hidden until mere_way_known.

  Passage ash_way "the ash road" is road between veil_foot and ash_road taking 2 hours.
  Passage cinder_way "the slope of the cinder hollow" is path between ash_road and cinders taking 1 hour.
  Passage mere_way "the mere path" is path between cinders and mere_edge taking 1 hour.
  Passage shore_walk "the shore of the Ash Mere" is path between mere_edge and drowned_stair taking 1 hour.
  Passage arch_way "the Arch road" is road between ash_road and arch taking 2 hours.
  Passage door_walk "the walk under the Arch" is path between arch and lamp_door taking 30 minutes.
  Passage lampfall_way "Lampfall's causeway" is causeway between ash_road and gate_ward taking 1 hour.
  Passage keep_door "the keep door" is door between gate_ward and ledger_hall.
  Passage vault_door "the vault door" is door between ledger_hall and jar_vault.
  Passage beacon_stair "the beacon stair" is stair between ledger_hall and beacon_room.

  Observe veil_scene at veil_foot when true "You stand on ash under no sky. Above you, very far up, the Lanthorn's cellar is a pale smudge, like a window seen from the bottom of a well. Your light falls a few feet and stops.".
  Observe road_scene at ash_road when true "A road of laid stone runs across the ash, lamp-posts every hundred paces, every lamp dead. Far off to one side something stands up out of the plain with a tower on it.".
  Observe cinder_scene at cinders when true "A hollow full of cinders that were once something else: furniture, books, a cart. Things move at the edge of your light and are gone.".
  Observe mere_scene at mere_edge when true "The Ash Mere: a lake of fine grey dust, flat as water, going off into the dark. Here and there it dimples, as if something under it breathed.".
  Observe stair_scene at drowned_stair when true "Steps come up out of the dust here, wet, as if from under water. Above them the dark is a little less dark.".
  Observe arch_scene at arch when true "A great arch stands by itself on the plain, carved all over with lamps. Something hangs in it like a spider in a doorway: a round body of plates, and too many eyes, and every eye turned on you.".
  Observe door_scene at lamp_door when true "Past the arch, a door stands in the ash with no wall round it: oak, iron-bound, a brass lamp-and-hand on it, a keyhole the shape of a seal.".
  Observe gate_scene at gate_ward when true "Lampfall's gate stands open. Inside, the outer court is full of lamp-posts in rows like an orchard, all dead.".
  Observe hall_scene at ledger_hall when true "The ledger hall: shelves of ledgers to a ceiling lost in dark, and at a desk in the middle something in a Lamplighter's robes writing by no light at all.".
  Observe vault_scene at jar_vault when true "The jar vault: racks of jars, most of them dark, a few still burning low, like coals at the end of a night.".
  Observe beacon_scene at beacon_room when not kindled_here(beacon_room) "The beacon room: a cradle of mirrors around an empty bowl, and a shaft above it going up into nothing.".
  Observe beacon_lit at beacon_room when kindled_here(beacon_room) "The beacon burns in Lampfall's cradle, and the mirrors throw noon across the Ash as far as you can see.".

  // The shades: what is left of those who came down after light and did not go back. They keep away from the living,
  // and cannot bear the sun; cornered in their hollow they fight.
  Person shades "the shades" at ash_road {
    Role "the grey dead of the Ash". Species spirit. Level 6. Numbers 4.
  }
  Initially Assert temperament(shades, temper_wary). Initially Assert refuge(shades, cinders).
  Initially Assert fears(shades, sunlight). Initially Assert flinch(shades, shades_flee). Initially Assert onslaught(shades, shades_turn).
  Entity shades_flee: fact "Grey shapes that were watching you from the edge of your light draw back into the dark, toward the cinder hollow.".
  Entity shades_turn: fact "In the cinder hollow there is nowhere left for the shades to go. They come at you out of the cinders, cold as wells.".
  // The wraiths ride the road: they fall on whatever is on it, and go up and down it all the time.
  Person wraiths "the wraith riders" at arch {
    Role "the riders of the ash road". Species wraith. Level 9. Numbers 3.
  }
  Initially Assert temperament(wraiths, temper_savage). Initially Assert onslaught(wraiths, wraiths_come).
  Entity wraiths_come: fact "Out of the dark along the road, three riders without faces, on horses made of nothing, come at you at a gallop.".
  Rule wraiths_ride when at(wraiths, arch) and able(wraiths) and not together(wraiths, party) and dice(clock) <= 15 { Assert at(wraiths, ash_road). }
  Rule wraiths_return when at(wraiths, ash_road) and able(wraiths) and not together(wraiths, party) and dice(clock) <= 15 { Assert at(wraiths, arch). }
  // The Mere's mouth: it lies under the dust and strikes, unless someone sees the dust breathe first.
  Person mouther "the thing under the Mere" at mere_edge {
    Role "a mouth in the dust". Species mouther. Level 10.
  }
  Initially Assert temperament(mouther, temper_ambush). Initially Assert warning(mouther, mouther_seen).
  Initially Assert onslaught(mouther, mouther_rises).
  Entity mouther_seen: fact "The dust at the Mere's edge breathes in, and out, in a ring a cart wide. There is something under it, and it has noticed you.".
  Entity mouther_rises: fact "The dust at your feet opens into a mouth.".
  // The Watcher in the Arch keeps the Lamplighters' door, and lets by only those who carry the Charter's seal.
  Entity lamplighter_seal: itemkind "Lamplighters' seal".
  Person watcher "the Watcher in the Arch" at arch {
    Role "the keeper of the Arch of Ways". Species discerner. Level 12.
  }
  Initially Assert temperament(watcher, temper_obedient). Initially Assert lair(watcher, arch).
  Initially Assert onslaught(watcher, watcher_wakes).
  Entity watcher_wakes: fact "Every eye in the Arch opens at once, and the Watcher unfolds out of it.".
  Rule watcher_knows_seal when together(watcher, party) and holding(party, lamplighter_seal) and not tolerates(watcher, party)
    says "The Watcher's eyes go to the seal you carry, one after another, and close. It folds itself back into the Arch and lets you by." {
    Assert tolerates(watcher, party).
  }

  // The Hollow Warden: the last warden of Lampfall, who shut the doors with the light inside and himself with it. He
  // keeps the ledger of every jar, and names a price for leaving; he will take coin, or better, light.
  Person hollow "the Hollow Warden" at ledger_hall {
    Role "the last warden of Lampfall, dead and not gone". Species lich. Level 14.
    State writing "The thing in the Lamplighter's robes writes on, a line to every jar, and does not look up.".
  }
  Person hollow_guard "the warden's lamp-bearers" at gate_ward {
    Role "the warden's dead servants". Species ghoul. Level 8. Numbers 2.
  }
  Initially Assert temperament(hollow, temper_proud). Initially Assert lair(hollow, ledger_hall).
  Initially Assert warning(hollow, hollow_price). Initially Assert onslaught(hollow, hollow_rises). Initially Set tribute(hollow) to 120.
  Entity hollow_price: fact "'A hundred and twenty crowns,' says the Hollow Warden without looking up, 'for the light you burned on my road. Or a jar of noon, which is better than crowns. Or stay, and go in the ledger with the rest.'".
  Entity hollow_rises: fact "The Hollow Warden lays down his pen. 'Entered,' he says, and stands.".
  Initially Assert temperament(hollow_guard, temper_territorial). Initially Assert warning(hollow_guard, guard_warns).
  Initially Assert onslaught(hollow_guard, guard_comes).
  Entity guard_warns: fact "Two dead men in the Lamplighters' grey stand up from the gate steps and lift their dark lamps at you. They do not need to speak.".
  Entity guard_comes: fact "The lamp-bearers come down the steps at you, swinging the iron lamps like flails.".
  Action pay_in_light(actor: group, site: place) "Give the Hollow Warden a jar of noonlight" {
    Requires able(actor) and company(actor) and at(actor, site) and at(hollow, site) and able(hollow)
      and warned(hollow, actor) and holding(actor, noonlight).
    On success { Assert tolerates(hollow, actor). Retract warned(hollow, actor). Assert paid_in_light(actor). }
    Result "The Hollow Warden takes the jar in both hands and holds it to where his face was. 'Entered,' he says, and writes, and does not look at you again until you ask him something.".
  }
  Relation paid_in_light(group).
  Topic hollow_door with hollow "Ask the Hollow Warden about the way to the sea" when tolerates(hollow, party) once {
    Says "'The Lamplighters had a door for every beacon,' says the Hollow Warden. 'The Lanthorn's, under its deep cellar. The one under the lake. And the one past the Arch, to the hall in Brack where they kept the Charter. The Watcher keeps it for them still, and lets by only the seal.'".
    On discuss { Assert knows(actor, brack_door_known). }
  }
  Entity brack_door_known: fact "Past the Arch of Ways in the Unlit stands the Lamplighters' door to their hall in Brack, kept by the Watcher, who lets by only those carrying the Charter's seal.".
  Initially Assert established(brack_door_known).

  // The jar vault: the light the Lamplighters laid down, and what the Hollow Warden took from his own order.
  Thing vault_racks "the vault racks" at jar_vault {
    Holds.
  }
  Item vault_noon "a burning jar of noonlight" is noonlight in vault_racks.
  Item vault_noon_two "a second jar of noonlight" is noonlight in vault_racks.
  Item vault_moon "a jar of moonlight" is moonlight in vault_racks.
  Item last_light "the Last Light of Lampfall" is first_light in vault_racks.
  Item regalia "the Lamplighters' regalia" is hollow_regalia at ledger_hall.
  // Whatever was agreed, his order's regalia taken from under his pen ends it.
  Rule regalia_stolen when holding(party, hollow_regalia) and together(hollow, party) and able(hollow)
    and not assails(hollow, party) says "The pen stops. 'That,' says the Hollow Warden, 'was never in the ledger.' He stands." {
    Retract tolerates(hollow, party). Assert assails(hollow, party).
  }
  Observe vault_guarded at jar_vault when able(hollow) and not tolerates(hollow, party) "Every jar on the racks has a line in the ledger, and you can feel the ledger knowing you are here.".
  Rule vault_robbed when at(party, jar_vault) and able(hollow) and not tolerates(hollow, party) and not warned(hollow, party)
    and not assails(hollow, party) says "Out in the hall the pen stops." {
    Assert at(hollow, jar_vault). Assert assails(hollow, party).
  }
  // The Last Light is the ledger's first line: whatever was paid for passage, he comes for whoever takes it.
  Relation in_lampfall(place).
  Initially Assert in_lampfall(gate_ward). Initially Assert in_lampfall(ledger_hall). Initially Assert in_lampfall(jar_vault).
  Initially Assert in_lampfall(beacon_room).
  Rule last_light_taken when holding(party, first_light) and able(hollow) and at(party, ?p) and in_lampfall(?p)
    and not assails(hollow, party) says "Far off in the ledger hall a pen stops, and a chair scrapes." {
    Retract tolerates(hollow, party). Assert at(hollow, ?p). Assert assails(hollow, party).
  }

  // Lampfall's beacon: a Last Light in its cradle relights it, and the Unlit's law changes where the light reaches.
  Thing far_cradle "Lampfall's beacon cradle" at beacon_room {
    Holds.
    State dark "The cradle of mirrors is empty and cold.".
  }
  Relation kindled_here(place).
  Rule lampfall_lit when inside(?jar, far_cradle) and itemKind(?jar, first_light) and not kindled_here(beacon_room)
    says "Noon leaps up out of the cradle and the mirrors take it and throw it out over the Ash. For the first time in a hundred years the lamp-posts on the ash road have shadows." {
    Assert kindled_here(beacon_room). Retract law(unlit, unlit_law). Assert law(unlit, beacon_law).
    Retract lightless(beacon_room). Retract lightless(ledger_hall). Retract lightless(jar_vault). Retract lightless(gate_ward).
    Retract lightless(ash_road). Retract lightless(veil_foot). Retract lightless(arch).
  }
  Rule shades_go when kindled_here(beacon_room) and able(shades) and not at(shades, cinders)
    says "Under the beacon's light the shades on the road thin like smoke and are gone." {
    Assert at(shades, cinders). Assert routed(shades).
  }
  Objective lampfall_seen when knows(party, brack_door_known) "Past the Arch of Ways in the Unlit, a door opens on the Lamplighters' hall in Brack.".
  Goal kindled_here(beacon_room) or paid_in_light(party).
}

data/regions/brack/region.kyr:
Module brack "Brack" {
  Description "The port at the mouth of the Varrow, two days down the salt road from Hollin: salt pans, quays, and the Salt Exchange that buys whatever the valley sends down, Skerry's silver above all. The Lamplighters kept their Charter here, in a hall on the harbour, and a few of them still do.".
  Entity party: group "Your company".
  // Where Brack touches the Varrow and the Unlit: the salt road from Hollin, the Gap the Exchange cares about, and
  // the Lamplighters' door on the far side of the dark.
  Place hollin_market "Hollin market" is room.
  Place toll_gate "The road below the Lanthorn's gate" is room.
  Place gate_passage "The Lanthorn's gate passage" is room.
  Place lamp_door "The Lamplighters' door in the Unlit" is room.
  Entity unlight: scenery "The Unlight". Entity unlight_gone: condition "gone".
  Entity brack_door_known: fact "The Lamplighters' door past the Arch of Ways opens on Brack.".

  Place saltmouth "the Saltmouth" is region.
  Place brack "Brack" is settlement within saltmouth at 1, 1.
  Place road_down "the salt road" is wilderness within saltmouth at 0, 1.
  Place exchange_house "the Salt Exchange" is building within brack.
  Place hall_house "the Charter's hall" is building within brack.
  Place gull_house "the Gull and Anchor" is building within brack.
  Place temple_house "the mother-temple of the Kindly Lamp" is building within brack.
  Place hall_under "the hall's undercroft" is level within hall_house.
  Place pans "the salt pans" is room within road_down at 0, 0.
  Place landgate "the Landgate" is room within brack at 0, 1.
  Place quays "the Saltquays" is room within brack at 1, 1.
  Place warrens "the Warrens" is room within brack at 1, 2.
  Place temple_hill "Temple Hill" is room within brack at 0, 0.
  Place exchange_floor "the Exchange floor" is room within exchange_house at 2, 1.
  Place counting_house "the counting-house" is room within exchange_house at 3, 1.
  Place strongroom "the strongroom" is room within exchange_house at 3, 2.
  Place gull "the Gull's taproom" is room within gull_house at 1, 0.
  Place temple "the mother-temple" is room within temple_house at 0, 0.
  Place hall_porch "the Charter's porch" is room within hall_house at 2, 0.
  Place archive "the Charter's archive" is room within hall_house at 3, 0.
  Place hall_cellar "the Charter's cellar" is room within hall_under at 3, 1.
  Initially Assert unlit(hall_cellar). Initially Assert unlit(strongroom).

  Passage salt_road "the salt road" is road between hollin_market and pans taking 14 hours.
  Passage pans_road "the causeway across the pans" is causeway between pans and landgate taking 2 hours.
  Passage gate_street "the Landgate street" is road between landgate and quays.
  Passage hill_steps "the steps up Temple Hill" is steps between landgate and temple_hill.
  Passage warren_alley "the alleys into the Warrens" is path between quays and warrens.
  Passage exchange_doors "the Exchange's doors" is door between quays and exchange_floor.
  Passage counting_door "the counting-house door" is door between exchange_floor and counting_house.
  Passage strong_door "the strongroom door" is door between counting_house and strongroom.
  Passage gull_door "the Gull's door" is door between gull and quays.
  Passage temple_door "the temple door" is doorway between temple and temple_hill.
  Passage hall_door "the Charter's door" is door between hall_porch and quays.
  Passage archive_door "the archive door" is door between hall_porch and archive.
  Passage cellar_stair "the cellar stair" is stair between archive and hall_cellar.
  // The Lamplighters' door: from the Charter's cellar into the Unlit, past the Arch of Ways, for whoever has heard of it.
  Passage lamp_way "the Lamplighters' door" is portal between hall_cellar and lamp_door taking 1 hour hidden until brack_door_known.

  Observe pans_scene at pans when true "Salt pans, square and shining, going out to the sea on both sides of a raised causeway. Brack is at the end of it: a wall, a gate, and a harbour full of masts.".
  Observe gate_scene at landgate when true "The Landgate: a stone arch with the Watch's lantern over it, and a board of tolls and permissions as long as a sermon.".
  Observe quay_scene at quays when true "The Saltquays: ships tied up three deep, barrows of salt, gulls, and the Salt Exchange's front of grey stone with its doors open onto the water.".
  Observe warren_scene at warrens when true "The Warrens: lanes too narrow for a cart, washing across them, and doorways with someone in every one, watching.".
  Observe hill_scene at temple_hill when true "Temple Hill looks over the whole harbour. On top, the mother-temple of the Kindly Lamp, all lamps and no images, like Mother Ash's in Hollin but forty times the size.".
  Observe floor_scene at exchange_floor when true "The Exchange floor: a hall of slates chalked with prices, factors shouting, and a great balance in the middle with a clerk on a stool beside it.".
  Observe counting_scene at counting_house when true "The counting-house: desks, ledgers on chains, and a door bound in iron at the back.".
  Observe strong_scene at strongroom when true "The strongroom: chests, a strong-box for every factor, and a shelf of ledgers bound in black.".
  Observe gull_scene at gull when true "A taproom full of sailors and salt-carters. Everyone here has an opinion about the Exchange.".
  Observe temple_scene at temple when true "Lamps on chains, lamps in niches, lamps in a great iron wheel like Hollin's, and a priest moving among them with a taper.".
  Observe porch_scene at hall_porch when true "The Charter's porch: a brass lamp-and-hand over the door, gone green, and a bench where an old man sits with a ledger.".
  Observe archive_scene at archive when true "The Charter's archive: shelves of the Lamplighters' ledgers, maps of beacons that stood from the Thrumm to the sea, and dust.".
  Observe cellar_scene at hall_cellar when true "The Charter's cellar: racks of empty jars, and at the back an oak door bound in iron, with a brass lamp-and-hand on it, set in the rock.".

  // The Exchange and the Gap: silver is dear in Brack while the Gap is tolled, and Hollin's unsold grain comes down
  // the salt road and is cheap. Open, silver comes down and grain goes up.
  Observe floor_tolled at exchange_floor when tolls(?collector, toll_gate) "The slate for Skerry silver reads high and rising, and the one for Hollin grain reads lower than anyone here remembers.".
  Observe floor_open at exchange_floor when not tolls(?collector, toll_gate) "Skerry silver is coming down the salt road in carts again; its slate has fallen by half, and the grain-factors are buying for the hill towns.".

  // The Watch: strangers come in at the Landgate, and need the Watch's leave to be in the Exchange or the Charter's
  // hall after dark.
  Person morrow "Sergeant Morrow" at landgate {
    Role "sergeant of the Harbour Watch at the Landgate". Ancestry human. Calling warrior. Level 5. Peaceable.
  }
  Relation passed(group).
  Action buy_papers(actor: group, site: place) "Pay Sergeant Morrow two coin for a stranger's pass" {
    Requires able(actor) and company(actor) and at(actor, site) and at(morrow, site) and not passed(actor)
      and quantity(actor, gold) >= 2.
    On success { Decrease quantity(actor, gold) by 2. Increase quantity(morrow, gold) by 2. Assert passed(actor). }
    Result "Morrow writes your names in his book slowly, spelling them wrong, and hands you a wooden tally with the Watch's lantern burned into it.".
  }
  Person night_watch "the Harbour Watch" at quays {
    Role "the Watch on the quays after dark". Ancestry human. Calling warrior. Level 4. Numbers 4.
  }
  Relation challenged(group).
  Rule watch_challenges when dark() and together(night_watch, party) and not passed(party) and not challenged(party)
    and not tolerates(night_watch, party)
    says "A lantern swings up in your faces. 'Stranger's tally,' says the Watch, 'or the lock-up till morning.'" {
    Assert challenged(party). Assert halts(night_watch, party).
  }
  Rule watch_waves when together(night_watch, party) and passed(party) and halts(night_watch, party) { Retract halts(night_watch, party). }
  Rule watch_forgets when not together(night_watch, party) and challenged(party) { Retract challenged(party). }
  Rule watch_shuts when dark() and passed(party) and at(party, warrens) { Retract passed(party). }

  // The Salt Exchange: Dame Ysolde Marrick, who keeps it, and Corvin Hale, her factor for silver, who has been paying
  // Ninefingers to hold the Gap so that Skerry's silver comes to Brack cheap through his own agents and to no one else.
  Person marrick "Dame Ysolde Marrick" at exchange_floor {
    Role "warden of the Salt Exchange". Ancestry human. Calling bard. Level 7. Peaceable.
  }
  Person hale "Corvin Hale" at counting_house {
    Role "the Exchange's factor for silver". Ancestry human. Calling thief. Level 6. Peaceable.
    Buys toll_silver for 30 coin. Buys sun_disc for 50 coin. Buys hollow_regalia for 120 coin.
  }
  Initially Set quantity(hale, gold) to 400.
  Person pim "Pim" at counting_house {
    Role "a clerk of the counting-house". Ancestry human. Peaceable.
  }
  Person exchange_guards "the Exchange's guards" at exchange_floor {
    Role "the Exchange's hired swords". Ancestry human. Calling warrior. Level 5. Numbers 4.
  }
  Initially Assert serves(exchange_guards, hale). Initially Assert posts(exchange_guards, hale).
  // What Hale wants: the Lanthorn's gate, if it is ever left empty, and the Toll for himself.
  Initially Assert covets(hale, gate_passage).
  Relation exposed(group).
  Rule hale_tolls when holds(hale, gate_passage) and able(exchange_guards) and not exposed(hale) and not tolls(exchange_guards, toll_gate)
    says "Word comes down the salt road: the Exchange's guards have moved into the Lanthorn, and there is a toll on the Gap again, with the Exchange's seal on the board." {
    Assert tolls(exchange_guards, toll_gate). Assert at(exchange_guards, gate_passage).
  }
  Rule hale_falls when exposed(hale) and tolls(exchange_guards, toll_gate) { Retract tolls(exchange_guards, toll_gate). }
  Rule hale_unwanted when exposed(hale) and covets(hale, gate_passage) { Retract covets(hale, gate_passage). }

  Entity toll_bought: fact "Corvin Hale, the Salt Exchange's factor for silver, has paid Ninefingers every month since spring to hold the Gap, so that Skerry's silver comes to Brack cheap through his agents and to nobody else.".
  Initially Assert established(toll_bought).
  Item black_ledger "a ledger bound in black" is exchange_ledger at strongroom.
  Observe ledger_read at strongroom when holding(party, exchange_ledger) "The black ledger is in a clerk's hand, and it is plain enough: forty crowns a month, out of the strongroom, to 'O.N., at the Gap'. The signature under every entry is Corvin Hale's." teaches toll_bought.
  // Pim knows, and is afraid, and would like to be paid for being afraid.
  Topic pim_nerves with pim "Ask Pim what is wrong" when true once {
    Says "Pim looks at the strongroom door and then at you. 'Nothing,' he says. 'Only some ledgers aren't kept on the chains, and some are kept in black, and I'd not like to be the one who shows anyone which.'".
  }
  Action bribe_pim(actor: group, site: place) "Pay Pim ten coin to leave the strongroom key on his desk" {
    Requires able(actor) and company(actor) and at(actor, site) and at(pim, site) and quantity(actor, gold) >= 10
      and state(strong_lock, locked).
    On success { Decrease quantity(actor, gold) by 10. Increase quantity(pim, gold) by 10. Assert state(strong_lock, open). }
    Result "Pim pockets the coins without looking at them, and goes out for some air, and the key is on his desk.".
  }
  Thing strong_lock "the strongroom lock" on strong_door {
    State locked blocking "The strongroom door is shut and locked: iron, with a lock the size of a book.".
    State open "The strongroom door stands open.".
    Change pick "Pick the strongroom lock" from locked to open needing lockwork.
  }
  // Infiltration: at night the Exchange is shut and guarded; the Warrens know a way in over the roofs.
  Thing exchange_shutters "the Exchange's shutters" on exchange_doors {
    State open "The Exchange's doors stand open onto the quay.".
    State barred blocking "The Exchange's doors are barred for the night.".
  }
  Rule exchange_shuts when dark() and state(exchange_shutters, open) and not at(party, exchange_floor) and not at(party, counting_house)
    and not at(party, strongroom) { Assert state(exchange_shutters, barred). }
  Rule exchange_opens when not dark() and state(exchange_shutters, barred) { Assert state(exchange_shutters, open). }
  Person quill "Nan Quill" at warrens {
    Role "a fence, and fixer of the Gutter-Guild". Ancestry human. Calling thief. Level 6. Peaceable.
    Buys grave_rings for 13 coin. Buys chapel_plate for 20 coin. Buys jade_idol for 28 coin. Buys hollow_regalia for 150 coin.
    Buys exchange_ledger for 40 coin.
  }
  Initially Set quantity(quill, gold) to 250.
  Entity roof_way_known: fact "From the Warrens a way goes over the roofs and down a chimney into the Exchange's counting-house, when the Exchange is shut.".
  Initially Assert established(roof_way_known).
  Topic quill_roofs with quill "Ask Nan Quill how a body gets into the Exchange at night" when true once {
    Says "'Over the roofs,' says Nan, 'from my back yard to the Exchange's chimney, and down into the counting-house. Hale's strongroom you'll need a picklock for, or Pim, who's for sale. And bring me whatever you find in black; I've buyers who'd pay to see Hale sweat.'".
    On discuss { Assert knows(actor, roof_way_known). }
  }
  Passage roof_way "the way over the roofs" is climb between warrens and counting_house taking 1 hour hidden until roof_way_known needing climbing or rope.

  // Negotiation: confront Hale with what you know, and take his money; or take it to Marrick.
  Relation hush_paid(group).
  Topic hale_confronted with hale "Tell Corvin Hale what you know about the Toll" when knows(actor, toll_bought) and not exposed(hale) and not hush_paid(actor) once {
    Says "Hale goes very still, then smiles, and reaches for his strong-box. 'A hundred crowns,' he says, 'and you never read anything, and Dame Marrick hears nothing. Think what the Gap is to you, and what a hundred crowns is.'".
  }
  Action take_hush(actor: group, site: place) "Take Corvin Hale's hundred crowns to keep quiet" {
    Requires able(actor) and company(actor) and at(actor, site) and at(hale, site) and knows(actor, toll_bought)
      and not exposed(hale) and not hush_paid(actor) and quantity(hale, gold) >= 100.
    On success { Decrease quantity(hale, gold) by 100. Increase quantity(actor, gold) by 100. Assert hush_paid(actor). }
    Result "Hale counts it out in silver. Skerry silver.".
  }
  Topic marrick_told with marrick "Tell Dame Marrick what her factor has been paying for" when knows(actor, toll_bought) and not exposed(hale) once {
    Says "Dame Marrick reads the black ledger to the last line without a word, closes it, and sends for the Watch. 'The Exchange buys,' she says. 'It does not hire cut-throats to make the price. Hale is done. And you are owed: name the Exchange your friend, and it will be one.'".
    On discuss { Assert exposed(hale). Assert patron(marrick, actor). Assert at(hale, landgate). Assert peaceable(hale). }
  }
  Relation patron(group, group).
  Rule patron_pays when patron(marrick, party) and not rewarded(party) says "A clerk of the Exchange finds you with a purse of eighty crowns, and Dame Marrick's compliments." {
    Assert rewarded(party). Increase quantity(party, gold) by 80.
  }
  Relation rewarded(group).
  // A friend of the Exchange, with the Gap open, sends grain up the river to Hollin.
  Person ferro "Captain Ferro" at quays {
    Role "master of a grain barge". Ancestry human. Peaceable.
  }
  Relation barges_up(group).
  Topic ferro_grain with ferro "Ask Captain Ferro to take grain up the Varrow" when patron(marrick, actor) and not tolls(?collector, toll_gate) once {
    Says "'With the Exchange's writ and the Gap open?' says Ferro. 'I'll have three barges at Hollin's quay by the end of the week, and the hill towns eating by the next.'".
    On discuss { Assert barges_up(ferro). }
  }

  // The Charter: what is left of the Lamplighters. Warden Sabelle Orme will make the company the Charter's friends,
  // with the seal that the Lamplighters' old doors answer to, for the Lanthorn's Unlight burnt out, or Lampfall's
  // regalia brought home.
  Person orme "Warden Sabelle Orme" at hall_porch {
    Role "warden of the Lamplighters' Charter". Ancestry human. Calling cleric. Level 9. Peaceable.
    Offers healing "the Charter's salves, and an hour by the hall fire" for 5 coin.
  }
  Person tobit "Tobit" at archive {
    Role "the Charter's archivist". Ancestry human. Calling mage. Level 6. Peaceable.
  }
  Thing archive_lock "the archive door's lock" on archive_door {
    State locked blocking "The archive door is locked, and Warden Orme keeps the key.".
    State open "The archive door stands open.".
    Change pick "Pick the archive lock" from locked to open needing lockwork.
  }
  Relation chartered(group).
  Topic orme_charter with orme "Ask Warden Orme about the Lamplighters" when true once {
    Says "'We kept the light,' says Warden Orme, 'from the Thrumm to the sea, beacon by beacon, and laid down what we did not burn in the cellars of the world, where light keeps. Then the cellars soured, and the last warden of Lampfall shut the doors with the light inside. We are seven now, and we keep the ledgers, and nobody listens. Burn out the dark under the Lanthorn, or bring me Lampfall's regalia out of the Unlit, and the Charter will call you friends.'".
  }
  Topic orme_lanthorn with orme "Tell Warden Orme the Unlight under the Lanthorn is gone" when state(unlight, unlight_gone) and not chartered(actor) once {
    Says "Warden Orme closes her eyes for a long moment. 'Then the beacon burns at the Gap again,' she says. 'Take this. Our doors know it.' It is a brass seal on a chain, a lamp with a hand round it.".
    On discuss { Assert chartered(actor). Assert state(archive_lock, open). }
  }
  Item charter_seal "a Lamplighters' seal" is lamplighter_seal at hall_porch hidden until charter_friends.
  Entity charter_friends: fact "Warden Orme has given the company the Charter's seal, which the Lamplighters' old doors answer to.".
  Initially Assert established(charter_friends).
  Observe seal_given at hall_porch when chartered(party) "Warden Orme's seal lies on the bench beside her ledger, waiting for you to take it." teaches charter_friends.
  Rule regalia_home when holding(party, hollow_regalia) and at(party, hall_porch) and not chartered(party)
    says "Warden Orme stands up when she sees the chain of lamps in your hands, and her ledger falls off her knee. 'Lampfall,' she says. 'You went to Lampfall.'" {
    Assert chartered(party). Assert state(archive_lock, open).
  }
  Topic tobit_doors with tobit "Ask Tobit about the Lamplighters' doors" when true once {
    Says "'Three doors,' says Tobit, and finds the map without looking. 'One under every beacon's cellar: the Lanthorn's, the one under the Glimmerkin's lake, and ours, below this floor. They all open on the same country, the Unlit, and in it past the Arch of Ways is our door's other side, kept by a thing the Charter set there that answers only to the seal.'".
    On discuss { Assert knows(actor, brack_door_known). }
  }
  Objective exchange_secret when knows(party, toll_bought) "Corvin Hale, the Salt Exchange's factor, has been paying Ninefingers to hold the Gap.".
  Objective charter_door when chartered(party) and knows(party, brack_door_known) "The Charter's seal opens the Lamplighters' door below their hall in Brack, into the Unlit.".
  Goal exposed(hale) or chartered(party).
}

data/regions/march-word/word.kyr:
Module march_word "Word around the March" {
  Description "What people in Reedwake, Chalkcross and Brackenholt know and will say: about the spiders under the downs, the light in Holt tower, the opened graves and the old well. Each says it in their own way, and only what they could know.".
  Entity party: group "Your company".
  Entity maud: group "Maud". Entity nera: group "Nera". Entity iven: group "Iven".
  Entity hedda: group "Hedda". Entity tam: group "Tam".
  Entity osric: group "Osric". Entity agnes: group "Agnes". Entity cutter: group "Wat".
  Entity ewes: fact "The ewes taken on the ridge". Entity no_silk: fact "Odile has no silk".
  Entity quarrel: thing "The quarrel over the brood". Entity over: condition "over".
  Entity lights: fact "The light in Holt tower". Entity graves: fact "The opened graves". Entity old_well: fact "The old well".
  Entity well: passage "The old well shaft".
  Entity stair_known: fact "The keepers' stair".
  Place tower_foot "Below the tower" is room.
  Place ridge "The ridge" is room.

  Initially Assert knows(maud, lights). Initially Assert knows(nera, no_silk). Initially Assert knows(iven, graves).
  Initially Assert knows(hedda, ewes). Initially Assert knows(tam, ewes).
  Initially Assert knows(osric, lights). Initially Assert knows(agnes, graves). Initially Assert knows(agnes, lights).
  Initially Assert knows(cutter, old_well). Initially Assert knows(iven, stair_known).
  Initially Assert revealedBy(well, old_well).

  Topic maud_lights with maud "Ask Maud what the bargemen are saying" when true once {
    Says "'That there's a light again in Holt tower over Brackenholt,' says Maud, 'green as a drowned man, and the Brackenholt folk keep to their doors after dark. Wren's ferry is the way across, when Wren's minded to take it.'".
    On discuss { Assert knows(actor, lights). }
  }
  Topic nera_silk with nera "Ask Nera why there is no silk on her shelves" when not state(quarrel, over) once {
    Says "'Odile hasn't sent down a hank in a week,' says Nera. 'She winds it at Silkholme, the sink up on the downs past the ridge. Something's wrong with her spiders, or with Garth's sheep, depending who you ask.'".
    On discuss { Assert knows(actor, no_silk). }
  }
  Topic iven_graves with iven "Ask Iven what troubles the keepers" when true once {
    Says "{iven} lowers his voice. 'Graves opened in Brackenholt churchyard, and the dead gone out of them. Not robbed: gone. I had an acolyte once who wanted to know what the dead would say if they could be made to speak. He left this shrine years ago, and they say he keeps Holt tower now.'".
    On discuss { Assert knows(actor, graves). }
  }
  Topic iven_stair with iven "Ask Iven, as one who keeps the rites, how the keepers went down to their dead" when capable(actor, rites) and not knows(actor, stair_known) once {
    Says "{iven} studies the one among you who knows the rites, then nods. 'Then you will go down as we did. Behind the shelves in the name room there is a stair the keepers cut, down to the family crypt. We did not carry our dead through the bronze court.'".
    On discuss { Assert knows(actor, stair_known). }
  }
  Topic hedda_ewes with hedda "Ask Hedda about Garth's flock" when not state(quarrel, over) once {
    Says "'A ewe a night off the ridge,' says Hedda, 'and Garth swearing it's Odile's spiders up out of Silkholme. He's got pitch and a torch ready. If he goes down that sink with fire there'll be no silk on the downs again.'".
    On discuss { Assert knows(actor, ewes). }
  }
  Topic tam_ewes with tam "Ask Tam what is taking the sheep" when not state(quarrel, over) once {
    Says "'Not wolves,' says Tam. 'Wolves leave a mess. Garth's ewes are just gone off the ridge in the night, and threads on the thorn in the morning like grey hair.'".
    On discuss { Assert knows(actor, ewes). }
  }
  Topic osric_lights with osric "Ask Osric about the light up the lane" when true once {
    Says "'Green, and only after dark,' says Osric. 'And things walk the lane under it that have no business walking. I've barred the shutters. Ask Agnes; she keeps the churchyard.'".
    On discuss { Assert knows(actor, lights). }
  }
  Topic agnes_graves with agnes "Ask Agnes what happened in the churchyard" when true once {
    Says "'Five graves open when I first went out, and the earth thrown out, not in,' says Agnes. 'I filled them myself, years back. The dead climbed out, and they went up the lane to the tower. I saw the last of them go.' Her hands will not keep still.".
    On discuss { Assert knows(actor, graves). Assert knows(actor, lights). }
  }
  Topic cutter_well with cutter "Ask Wat about the tower" when true once {
    Says "'The front door's iron and the stair inside is full of what walked up the lane,' says Wat. 'But my grandfather cut the oak for that tower, and there's an old well behind it the builders used, that runs down into the cellars. A rope gets you down.'".
    On discuss { Assert knows(actor, old_well). }
  }
  Goal false.
}

data/regions/varrow/region.kyr:
Module varrow "The Varrow" {
  Description "A high valley cut through the Thrumm by the Varrow river. The old salt road climbs from Hollin, the lowland market town, past Crake's Ford, over Gaunt's Gap to Skerry and its silver mine. Hollin wants Skerry's silver; Skerry eats Hollin's grain; the Gap is the lifeline, and someone has put a toll on it.".

  Place varrow "The Varrow" is region.
  Place hollin "Hollin" is settlement within varrow at 0, 1.
  Place lowroad "the Varrow road" is wilderness within varrow at 1, 1.
  Place ford "Crake's Ford" is settlement within varrow at 2, 1.
  Place downs "the Gorse Downs" is wilderness within varrow at 2, 2.
  Place climb "the Gap road" is wilderness within varrow at 3, 1.
  Place fell "Hushing Fell" is wilderness within varrow at 4, 0.
  Place heights "the Skerry heights" is wilderness within varrow at 4, 1.
  Place skerry "Skerry" is settlement within varrow at 5, 1.
  Initially Assert terrain(varrow, mountain). Initially Assert terrain(downs, hills). Initially Assert terrain(lowroad, hills).

  Place wheatsheaf_house "The Wheatsheaf" is building within hollin.
  Place chandlery_house "Ottar's chandlery" is building within hollin.
  Place vane_house "Vane's" is building within hollin.
  Place lamp_house "The Temple of the Kindly Lamp" is building within hollin.
  Place reeve_house "The reeve's hall" is building within hollin.
  Place heron_house "The Heron and Eel" is building within ford.
  Place smithy_house "Jory's smithy" is building within ford.
  Place pick_house "The Lamp and Pick" is building within skerry.
  Place assay_house "The Assay" is building within skerry.

  Place market "Hollin market" is room within hollin at 1, 1.
  Place wheatsheaf "the Wheatsheaf's taproom" is room within wheatsheaf_house at 0, 1.
  Place chandlery "Ottar's chandlery" is room within chandlery_house at 2, 1.
  Place goldsmith "Vane's counting-room" is room within vane_house at 1, 2.
  Place lamp_temple "the Temple of the Kindly Lamp" is room within lamp_house at 1, 0.
  Place reeve_hall "the reeve's hall" is room within reeve_house at 0, 2.
  Place barrows "Two Barrows" is room within lowroad at 0, 0.
  Place alders "the alder bend" is room within lowroad at 1, 0.
  Place ford_green "Crake's Ford" is room within ford at 0, 0.
  Place far_bank "the far bank of the ford" is room within ford at 1, 0.
  Place heron "the Heron and Eel" is room within heron_house at 0, 1.
  Place smithy "Jory's smithy" is room within smithy_house at 1, 1.
  Place drove_track "the drove track" is room within downs at 0, 0.
  Place stones "the Whispering Stones" is room within downs at 1, 0.
  Place knot_foot "below the Hob-Knot" is room within downs at 1, 1.
  Place switchbacks "the switchbacks" is room within climb at 0, 0.
  Place cairn "the wayside cairn" is room within climb at 1, 0.
  Place toll_gate "the Toll gate" is room within climb at 2, 0.
  Place shoulder "the shoulder of the fell" is room within fell at 0, 0.
  Place stair_foot "the foot of the pilgrims' stair" is room within fell at 1, 0.
  Place gap_far "the far side of the Gap" is room within heights at 0, 0.
  Place cairn_field "the cairn field" is room within heights at 1, 0.
  Place square "Skerry square" is room within skerry at 0, 0.
  Place pick_inn "the Lamp and Pick" is room within pick_house at 0, 1.
  Place assay "the Assay" is room within assay_house at 1, 1.
  Place mine_head "the mine head" is room within skerry at 1, 0.
  Place glimmer_stall "the Glimmerkin stall" is room within skerry at 2, 0.

  Passage wheatsheaf_door "the Wheatsheaf's door" is door between wheatsheaf and market.
  Passage chandlery_door "Ottar's door" is door between chandlery and market.
  Passage vane_door "Vane's door" is door between goldsmith and market.
  Passage temple_porch "the temple porch" is doorway between lamp_temple and market.
  Passage reeve_door "the reeve's door" is door between reeve_hall and market.
  Passage valley_road "the Varrow road" is road between market and barrows taking 3 hours.
  Passage river_road "the river road" is road between barrows and alders taking 1 hour.
  Passage alder_lane "the ford lane" is road between alders and ford_green taking 1 hour.
  Passage heron_door "the Heron's door" is door between heron and ford_green.
  Passage smithy_door "the smithy door" is doorway between smithy and ford_green.
  Passage the_ford "the ford" is ford between ford_green and far_bank taking 30 minutes.
  Passage downs_track "the drove track onto the downs" is track between ford_green and drove_track taking 1 hour.
  Passage stone_path "the stone path" is path between drove_track and stones taking 1 hour.
  Passage knot_path "the path below the ring-fort" is path between stones and knot_foot taking 30 minutes hidden until hob_knot_known.
  Passage gap_road "the Gap road" is road between far_bank and switchbacks taking 2 hours.
  Passage cairn_road "the road past the cairn" is road between switchbacks and cairn taking 1 hour.
  Passage toll_road "the last pull" is road between cairn and toll_gate taking 1 hour.
  Passage goat_path "the goat path over the shoulder" is climb between switchbacks and shoulder taking 3 hours hidden until goat_path_known needing climbing or rope.
  Passage shoulder_down "the scree slope" is path between shoulder and cairn_field taking 2 hours.
  Passage stair_path "the pilgrims' path" is path between shoulder and stair_foot taking 1 hour.
  Passage heights_road "the heights road" is road between gap_far and cairn_field taking 1 hour.
  Passage skerry_road "the road down into Skerry" is road between cairn_field and square taking 1 hour.
  Passage pick_door "the Lamp and Pick's door" is door between pick_inn and square.
  Passage assay_door "the Assay door" is door between assay and square.
  Passage mine_yard "the mine yard" is passage between square and mine_head.
  Passage stall_way "the awning by the mine head" is passage between mine_head and glimmer_stall.

  Company party "Your company" of 3 at market.
  Initially Set quantity(party, gold) to 15. Initially Set quantity(party, rations) to 2.

  // The weather turns before dawn: rain in the valley is snow on the high ground. Rain swells the ford; snow shuts
  // the goat path and slows the Gap road; fog hides the road's landmarks and those who wait beside it.
  Entity sky: scenery "the sky over the Varrow".
  Entity fair: condition "fair". Entity rain: condition "rain". Entity fog: condition "fog".
  Initially Assert state(sky, fair).
  Rule rain_comes when untilLight(clock) == 1 and state(sky, fair) and dice(clock) <= 25 { Assert state(sky, rain). }
  Rule fog_comes when untilLight(clock) == 1 and state(sky, fair) and dice(clock) > 25 and dice(clock) <= 40 { Assert state(sky, fog). }
  Rule clears when untilLight(clock) == 1 and not state(sky, fair) and dice(clock) > 55 { Assert state(sky, fair). }
  Thing spate "the Varrow at the ford" on the_ford is scenery {
    State fordable "The Varrow runs knee-deep and clear over the ford stones.".
    State swollen blocking "The Varrow is in spate, brown and loud, over the ford stones. Nobody crosses today.".
  }
  Rule ford_swells when state(sky, rain) and state(spate, fordable) { Assert state(spate, swollen). }
  Rule ford_falls when state(sky, fair) and state(spate, swollen) and untilLight(clock) == 2 { Assert state(spate, fordable). }
  Thing drifts "the snow on the shoulder" on goat_path is scenery {
    State clear "The goat path picks its way up the shoulder of the fell, steep but clear.".
    State drifted blocking "Snow has filled the goat path to the waist. Nobody goes over the shoulder until it melts.".
  }
  Rule snow_falls when state(sky, rain) and state(drifts, clear) { Assert state(drifts, drifted). }
  Rule snow_melts when state(sky, fair) and state(drifts, drifted) and untilLight(clock) == 3 { Assert state(drifts, clear). }
  Rule gap_slow when state(sky, rain) { Set travelTime(gap_road) to 18. Set travelTime(cairn_road) to 9. }
  Rule gap_fast when not state(sky, rain) { Set travelTime(gap_road) to 12. Set travelTime(cairn_road) to 6. }
  Observe rain_low at barrows when state(sky, rain) "Rain sweeps up the valley in grey curtains. The road is mud.".
  Observe rain_ford at ford_green when state(sky, rain) "Rain drums on the Heron's thatch.".
  Observe rain_high at switchbacks when state(sky, rain) "Sleet on the switchbacks, and snow higher up: the shoulder of the fell has gone white.".
  Observe fog_low at barrows when state(sky, fog) "Fog lies in the valley so thick the barrows are only shapes, and the road vanishes ten paces on.".
  Observe fog_high at cairn when state(sky, fog) "The cairn looms out of fog. Below, nothing; above, nothing.".

  // Hollin.
  Observe market_scene at market when tolls(?collector, toll_gate) "Hollin market: carts, a wool-cross, a well with a stone roof. Wagons for the Gap stand loaded and going nowhere; their drivers argue about the Toll.".
  Observe market_open at market when not tolls(?collector, toll_gate) "Hollin market: carts, a wool-cross, a well with a stone roof. Grain wagons are going out on the valley road toward the Gap, one after another.".
  Observe wheatsheaf_scene at wheatsheaf when true "A long low taproom smelling of beer and wet wool. A board by the hearth lists the Toll in chalk, and someone has added a rude drawing.".
  Observe chandlery_scene at chandlery when true "Coils of rope, poles in a rack, lamp-oil in stone jars and sacks of hard bread.".
  Observe goldsmith_scene at goldsmith when true "A narrow counting-room with a barred window, a balance under a glass bell, and a stone for testing gold.".
  Observe temple_scene at lamp_temple when true "A small temple with no images, only lamps: hundreds of them, in niches, on chains, in a great iron wheel, all kept burning.".
  Observe reeve_scene at reeve_hall when true "The reeve's hall is a counting-house with a dais. Ledgers lie open; most of the figures are red.".
  Person wenna "Wenna" at wheatsheaf {
    Role "keeper of the Wheatsheaf". Profession innkeeper. Peaceable.
    Sells rations for 2 coin from 8.
  }
  Person ottar "Ottar" at chandlery {
    Role "chandler". Profession herbalist. Peaceable.
    Sells torch for 1 coin from 8.
    Sells rope for 1 coin from 3.
    Sells pole for 1 coin from 2.
    Sells crowbar for 3 coin from 1.
    Sells rations for 2 coin from 6.
    Sells bandages for 1 coin from 4.
  }
  Person iselde "Iselde Vane" at goldsmith {
    Role "goldsmith". Ancestry human. Peaceable.
    Buys grave_rings for 12 coin. Buys chapel_plate for 18 coin. Buys jade_idol for 25 coin. Buys bronze_bearing for 8 coin.
    Buys toll_silver for 35 coin. Buys sun_disc for 45 coin. Buys gilt_crown for 2 coin. Buys gilt_sceptre for 1 coin.
    Buys noonlight for 30 coin. Buys moonlight for 12 coin. Buys first_light for 90 coin.
  }
  Initially Set quantity(iselde, gold) to 300.
  // Iselde's coin comes from Skerry's silver. While the Gap is tolled none comes down, and what she spends stays spent.
  Rule silver_comes when untilLight(clock) == 1 and not tolls(?collector, toll_gate) and quantity(iselde, gold) < 300 {
    Increase quantity(iselde, gold) by 30.
  }
  Person ash "Mother Ash" at lamp_temple {
    Role "keeper of the Kindly Lamp". Ancestry human. Calling cleric. Level 4. Profession priest. Peaceable.
    Offers healing "the lamp's oil on every wound, and a prayer" for 3 coin.
  }
  Person garrow "Aldous Garrow" at reeve_hall {
    Role "reeve of Hollin". Ancestry human. Peaceable.
  }
  Topic wenna_toll with wenna "Ask Wenna about the Toll" when tolls(?collector, toll_gate) {
    Says "'Ninefingers,' says Wenna, and spits in the fire. 'Ottilie Ninefingers and forty cut-throats, sitting in the old Lanthorn at the top of the Gap, and every cart that goes over pays her two crowns a wheel. Skerry's starving and we're drowning in unsold grain. The reeve's offering money to whoever shifts her.'".
  }
  Topic wenna_barrows with wenna "Ask Wenna what is said on the road" when true once {
    Says "'Carters coming down say there's lights at Two Barrows some nights,' says Wenna. 'Little lights, low down, going in and out of the mounds as if they owned them. And the Hobs are out again on the downs: they had the Midsummer wool off three carts last month, and Bryony Crake's sheep.'".
    On discuss { Assert knows(actor, barrow_lights). }
  }
  Topic garrow_bounty with garrow "Ask the reeve what he wants done about the Toll" when not knows(actor, bounty) once {
    Says "'Ottilie Ninefingers out of the Lanthorn,' says Garrow, 'dead, gone or paid off, I don't care which, and the Gap open. The town will pay fifty crowns. Her men are thieves, not soldiers, but there are a great many of them, and the Lanthorn was built to keep armies out. Nobody has been inside it in a hundred years who came back to talk about it, except Ninefingers.'".
    On discuss { Assert knows(actor, bounty). }
  }
  Topic ash_lanthorn with ash "Ask Mother Ash about the Lanthorn" when true once {
    Says "'The Lamplighters built it,' says Mother Ash, 'to hold a light at the top of the Gap that could be seen from the sea. They kept light the way you keep wine: bottled, laid down, aged. Something got into their cellars that ate it, and the beacon went out, and they went with it. This temple is what is left of them down here: we keep the lamps lit, because they asked us to, and nobody remembers why it matters.' She looks at the iron wheel of lamps. 'The lamps have been guttering this autumn. All of them, a little, every night.'".
    On discuss { Assert knows(actor, dimming). }
  }
  Entity barrow_lights: fact "Little lights are seen at Two Barrows on the Varrow road some nights, going in and out of the mounds.".
  Entity bounty: fact "The reeve of Hollin will pay fifty crowns to whoever ends the Toll at the Gap.".
  Entity dimming: fact "The Lamplighters who built the Lanthorn kept bottled light; something that eats light got into their cellars and put out their beacon. Hollin's temple lamps have been guttering all autumn.".
  Initially Assert established(barrow_lights). Initially Assert established(bounty). Initially Assert established(dimming).
  Objective end_toll when knows(party, bounty) "The reeve of Hollin will pay fifty crowns to whoever ends the Toll at the Gap.".

  // The Varrow road.
  Observe barrows_scene at barrows when not state(sky, fog) "Two grassy barrows stand by the road like a pair of sleeping cattle. The nearer has a dark slot low on its side, half hidden by brambles. Beyond them the valley narrows toward the ford.".
  Observe alders_scene at alders when true "The road bends with the river under alders. Someone has built a fishing platform out over the water, and a boat is pulled up beneath it.".
  Observe barrow_glow at barrows when dark() and not state(sky, fog) "Low down on the nearer barrow, a faint light moves behind the brambles, and goes out." teaches barrow_lights.

  // Crake's Ford.
  Observe ford_scene at ford_green when true "A hamlet of slate and turf at the ford of the Varrow: a dozen houses, the Heron and Eel, a smithy, and sheep-pens standing empty.".
  Observe far_bank_scene at far_bank when true "The far bank of the ford, where the Gap road leaves the river and starts to climb.".
  Observe heron_scene at heron when true "Eel-traps hang in the rafters. The fire is peat and the ale is thin.".
  Observe smithy_scene at smithy when true "The forge is banked and cold. Jory is sharpening scythes that nobody will use this year.".
  Person bryony "Bryony Crake" at heron {
    Role "keeper of the Heron and Eel". Profession innkeeper. Peaceable.
    Sells rations for 2 coin from 4.
  }
  // The Heron's meal comes off the ford's own farms, a sack a day; farms that have been robbed send nothing.
  Rule ford_bakes when untilLight(clock) == 1 and quantity(bryony, rations) < 8 and losses(ford_green) < 3 {
    Increase quantity(bryony, rations) by 1.
  }
  Observe heron_bare at heron when quantity(bryony, rations) <= 0 "The meal bin behind the bar stands open and empty.".
  Person jory "Jory" at smithy {
    Role "smith of Crake's Ford". Ancestry human. Peaceable.
    Sells pole for 1 coin from 1.
    Sells crowbar for 3 coin from 1.
  }
  Topic bryony_hobs with bryony "Ask Bryony about the Hobs" when true once {
    Says "'They come down off the downs at night when the moon's thin,' says Bryony, 'and take what isn't nailed down. They took my sheep, every one, and laughed doing it. Their ring-fort's somewhere past the Whispering Stones; my Tam followed them once as far as the stones and came back without his boots.'".
  }
  Topic bryony_toll with bryony "Ask Bryony about the Ninefingers" when true once {
    Says "'Her men come down for meal and ale,' says Bryony, 'on what they call credit. Every week. If they don't come one week, it means they're eating something else, and I'd like to know what.'".
  }
  Topic jory_path with jory "Ask Jory about getting over the Gap without paying" when true once {
    Says "Jory looks at the door before he answers. 'My brother takes salt over the shoulder of the fell by the goat path,' he says. 'Leave the road at the switchbacks, where a cairn of white stones marks a gully, and climb. You want a rope or a climber, and you want clear weather: snow fills it in an hour. It comes down in the cairn field above Skerry, behind the Toll.'".
    On discuss { Assert knows(actor, goat_path_known). }
  }
  Discovery goat_path_known "A goat path leaves the Gap road at the switchbacks, by a cairn of white stones, and climbs over the shoulder of Hushing Fell to the cairn field above Skerry, behind the Toll. It needs a rope or a climber, and clear weather." {
    Found by searching switchbacks with woodcraft "Up the gully by the white cairn: droppings, and the scrape of boot-nails on bare rock. A path, and someone uses it.".
  }
  Discovery hob_knot_known "The Hob-Knot, the Hobs' ring-fort, stands past the Whispering Stones on the Gorse Downs, by a path through the gorse." {
    Found by searching stones "Beyond the stones a path has been beaten through the gorse: narrow, and bloody with bramble scratches at the height of a short person.".
  }

  // The Gorse Downs.
  Observe drove_scene at drove_track when true "Gorse and heather, and the drove track wandering between them. Sheep-droppings, but no sheep.".
  Observe stones_scene at stones when true "A ring of nine grey stones, each taller than a man. The wind makes a sound in the gaps between them like people talking just out of hearing.".
  Observe knot_foot_scene at knot_foot when true "Below a hill crowned with a ring of earth and stakes. Smoke rises inside it. The stakes have things hung on them that turn in the wind.".

  // The Gap road.
  Observe switchbacks_scene at switchbacks when true "The road climbs in switchbacks above the river. A cairn of white stones stands by a gully where the road turns for the third time.".
  Observe cairn_scene at cairn when not state(sky, fog) "A wayside cairn of offerings: pins, buttons, a doll's shoe. Above, the road makes its last pull to the Gap, and the Lanthorn stands over it, black against the sky.".
  Observe toll_scene at toll_gate when tolls(?collector, toll_gate) "The road runs straight into a gatehouse built across the Gap. A board nailed to the gate reads TOLL: TWO CROWNS A WHEEL, TWO A HEAD, BY ORDER, and someone has scratched a ninth finger on the drawn hand.".
  Observe gate_scene at toll_gate when not tolls(?collector, toll_gate) "The road runs straight into a gatehouse built across the Gap.".

  // Hushing Fell and the heights.
  Observe shoulder_scene at shoulder when true "The shoulder of Hushing Fell: rock and old snow, and the whole Varrow laid out below. Up the fell, a stair has been cut into the rock, going up into cloud. A bell sounds from somewhere above, once.".
  Observe stair_foot_scene at stair_foot when true "The foot of a stair cut into the fell, worn into hollows by feet. A post by it holds a rope that goes up into the cloud, and a small bell.".
  Observe gap_far_scene at gap_far when true "Behind the Lanthorn the Gap opens onto the heights: stone, heather, and far off the smoke of Skerry.".
  Observe cairn_field_scene at cairn_field when true "A field of cairns, hundreds, each one a miner's grave. The road to Skerry runs between them.".

  // Skerry.
  Observe square_scene at square when tolls(?collector, toll_gate) "Skerry square: grey stone houses round a mine head with a great wheel. Everyone is thin. A queue at the Assay waits to sell silver nobody can carry down to Hollin.".
  Observe square_open at square when not tolls(?collector, toll_gate) "Skerry square: grey stone houses round a mine head with a great wheel. Silver goes down the Gap road in carts and grain comes up, and the Assay has a queue of carters.".
  Observe pick_scene at pick_inn when true "Miners' lamps hang over every table; half of them are out.".
  Observe assay_scene at assay when true "Scales, ingots stacked like bread, and an assayer who has not been paid in coin since summer.".
  Observe mine_head_scene at mine_head when true "The mine head: the wheel, the cage, and a cold breath coming up the shaft. A notice says DEEP GALLERIES CLOSED.".
  Observe stall_scene at glimmer_stall when true "Under the awning by the mine head, a stall hung with jars that glow: green, gold, white as noon.".
  Person hest "Captain Hest" at mine_head {
    Role "captain of the Skerry mine". Ancestry dwarf. Peaceable.
  }
  Person keld "Keld" at pick_inn {
    Role "keeper of the Lamp and Pick". Profession innkeeper. Peaceable.
    Sells rations for 3 coin from 3.
    Sells torch for 1 coin from 4.
  }
  // Skerry eats Hollin's grain. Tolled, it comes dear and seldom; open, the Gap brings it up every day.
  Rule skerry_dear when tolls(?collector, toll_gate) and goodsPrice(keld, rations) < 3 { Set goodsPrice(keld, rations) to 3. }
  Rule skerry_fed when not tolls(?collector, toll_gate) and goodsPrice(keld, rations) > 2 { Set goodsPrice(keld, rations) to 2. }
  Rule grain_comes when untilLight(clock) == 1 and not tolls(?collector, toll_gate) and quantity(keld, rations) < 8 {
    Increase quantity(keld, rations) by 2.
  }
  Topic hest_deep with hest "Ask Captain Hest about the deep galleries" when true once {
    Says "'We broke through into caves in the spring,' says Hest. 'Big ones, with folk in them: the Glimmerkin, little lantern-eyed people, who trade us light in jars. Then the lamps started going out in the deep galleries. Not blown out: eaten. You can watch a flame get smaller and smaller as if something was drinking it. I closed the deep galleries after two men went down and only their lamps came back, cold.'".
    On discuss { Assert knows(actor, lamps_eaten). }
  }
  Entity lamps_eaten: fact "In the deep galleries of the Skerry mine, lamps go out as if something drinks the flame; two miners were lost there.".
  Initially Assert established(lamps_eaten).

  Goal false.
}

data/rules/belongings.kyr:
Module belongings "What the company carries" {
  Kind item. Kind itemkind.
  Relation itemKind(item, itemkind). Relation ownedItem(item, member). Relation wearing(item, member).
  Relation forSale(item). Relation soldBy(item, group) exclusive. Relation wearable(itemkind). Relation consumable(itemkind).
  Relation canTrain(member, ability). Relation teaches(group, ability).
  Relation proficient(member, itemkind).
  Relation wants(group, itemkind). Measure pays(group, itemkind).
  Measure price(item).
  Goal false.
  Action take_item(actor: group, find: item, form: itemkind, recipient: member, site: place) "Collect {find} for {recipient}" {
    Requires able(actor) and at(actor, site) and at(find, site) and not forSale(find) and not benighted(actor)
      and itemKind(find, form) and memberOf(recipient, actor) and awake(recipient) and noticed(find, actor).
    Resolve acquire(find, form, recipient).
    On success { Retract at(find, site). }
    Result "{recipient} takes {find}.".
  }
  Action take_out(actor: group, find: item, form: itemkind, box: thing, recipient: member, site: place) "Take {find} out of {box} for {recipient}" {
    Requires able(actor) and at(actor, site) and at(box, site) and inside(find, box) and not shut(box)
      and noticed(box, actor) and noticed(find, actor) and not benighted(actor)
      and itemKind(find, form) and memberOf(recipient, actor) and awake(recipient).
    Resolve acquire(find, form, recipient).
    On success { Retract inside(find, box). }
    Result "{recipient} takes {find} out of {box}.".
  }
  Action put_in(actor: group, cargo: item, carrier: member, box: thing, site: place) "Put {cargo} in {box}" {
    Description "Set it in, on or into the thing, where it stays until someone takes it out.".
    Requires able(actor) and at(actor, site) and at(box, site) and receptacle(box) and not shut(box)
      and noticed(box, actor) and not benighted(actor)
      and memberOf(carrier, actor) and awake(carrier) and ownedItem(cargo, carrier).
    Resolve drop(cargo, carrier).
    On success { Assert inside(cargo, box). }
    Result "{carrier} puts {cargo} in {box}.".
  }
  Action buy_item(actor: group, find: item, form: itemkind, recipient: member, merchant: group, site: place) "Buy {find} for {recipient}" {
    Requires able(actor) and at(actor, site) and at(find, site) and forSale(find) and itemKind(find, form)
      and memberOf(recipient, actor) and awake(recipient) and soldBy(find, merchant)
      and able(merchant) and not refusesService(merchant, actor) and at(merchant, site) and distinct(actor, merchant) and quantity(actor, gold) >= price(find).
    Resolve purchase(find, form, recipient, actor, merchant).
    On success { Retract at(find, site). Retract forSale(find). }
    Result "{merchant} takes the money and hands it to {recipient}.".
  }
  Action equip_item(actor: group, tool: item, form: itemkind, wearer: member) "Equip {tool} on {wearer}" {
    Requires able(actor) and memberOf(wearer, actor) and awake(wearer) and ownedItem(tool, wearer)
      and itemKind(tool, form) and wearable(form) and proficient(wearer, form) and not wearing(tool, wearer).
    Resolve equip(tool, wearer).
    Result "{wearer} readies {tool}.".
  }
  Action use_item(actor: group, dose: item, form: itemkind, carrier: member, recipient: member) "Use {dose} on {recipient}" {
    Requires able(actor) and memberOf(carrier, actor) and memberOf(recipient, actor) and awake(carrier)
      and awake(recipient) and ownedItem(dose, carrier) and itemKind(dose, form) and consumable(form).
    Resolve consume(dose, carrier, recipient).
  }
  Action transfer_item(actor: group, cargo: item, carrier: member, recipient: member) "Give {cargo} to {recipient}" {
    Requires able(actor) and memberOf(carrier, actor) and memberOf(recipient, actor)
      and not ownedItem(cargo, recipient) and awake(recipient) and ownedItem(cargo, carrier).
    Resolve transfer_item(cargo, carrier, recipient).
    Result "{carrier} hands {cargo} to {recipient}.".
  }
  Action give(actor: group, gift: item, form: itemkind, carrier: member, recipient: group, site: place) "Give {gift} to {recipient}" {
    Description "Hand it to someone who has asked for it, or will take it. What they do with it is theirs to decide.".
    Requires able(actor) and at(actor, site) and able(recipient) and at(recipient, site) and distinct(actor, recipient)
      and memberOf(carrier, actor) and awake(carrier) and ownedItem(gift, carrier) and itemKind(gift, form)
      and wants(recipient, form).
    Resolve drop(gift, carrier).
    On success { Assert keeps(recipient, gift). }
    Result "{carrier} gives {gift} to {recipient}.".
  }
  Action sell(actor: group, ware: item, form: itemkind, carrier: member, buyer: group, site: place) "Sell {ware} to {buyer}" {
    Description "Someone who buys this kind of thing pays what they said they would, if they have the coin.".
    Requires able(actor) and at(actor, site) and able(buyer) and at(buyer, site) and distinct(actor, buyer)
      and memberOf(carrier, actor) and awake(carrier) and ownedItem(ware, carrier) and itemKind(ware, form)
      and pays(buyer, form) >= 1 and quantity(buyer, gold) >= pays(buyer, form) and not refusesService(buyer, actor).
    Resolve drop(ware, carrier).
    On success { Assert keeps(buyer, ware). Decrease quantity(buyer, gold) by pays(buyer, form).
      Increase quantity(actor, gold) by pays(buyer, form). }
    Result "{buyer} pays for {ware}.".
  }
  Action put_item(actor: group, cargo: item, carrier: member, site: place) "Set down {cargo}" {
    Requires able(actor) and at(actor, site) and memberOf(carrier, actor) and awake(carrier) and ownedItem(cargo, carrier).
    Resolve drop(cargo, carrier).
    On success { Assert at(cargo, site). }
    Result "{carrier} sets {cargo} down.".
  }
  Action train_member(actor: group, mentor: group, student: member, lesson: ability, site: place) "Train {student} in {lesson}" {
    Requires able(actor) and able(mentor) and distinct(actor, mentor) and at(actor, site) and at(mentor, site)
      and memberOf(student, actor) and awake(student) and teaches(mentor, lesson) and canTrain(student, lesson).
    Resolve train(lesson, student).
    Time 6.
    Result "{mentor} spends an hour drilling {student} in {lesson}.".
  }
}

data/rules/core.kyr:
Module world_core "Bodies, places, time and the shared catalog" {
  Kind group. Kind place. Kind good. Kind clock. Kind capability.
  Entity gold: good "coin". Entity rations: good "ration". Entity clock: clock "Time".
  Entity woodcraft: capability "Woodcraft". Entity mending: capability "Mending".
  Entity lockwork: capability "Lockwork". Entity trapwork: capability "Trapwork".
  Entity wayfinding: capability "Wayfinding". Entity digging: capability "Digging".
  Entity brawn: capability "Brawn". Entity stealth: capability "Stealth".
  Entity lore: capability "Lore". Entity rites: capability "Rites of the dead".
  Entity climbing: capability "Climbing". Entity light: capability "Light". Entity flame: capability "Flame".
  Entity sunlight: capability "Sunlight". Entity perception: capability "Keen eyes".
  // The lie of the land a region is: what a party's perks of place (an elven tribe in a forest) answer to.
  Kind terrainkind. Relation terrain(place, terrainkind).
  Entity forest: terrainkind "forest". Entity marsh: terrainkind "marsh". Entity mountain: terrainkind "mountain".
  Entity frost: terrainkind "frost". Entity desert: terrainkind "desert". Entity hills: terrainkind "hills".
  Relation at(entity, place) exclusive.
  Relation able(group). Relation dead(group). Relation distinct(group, group).
  Relation closed(place). Relation indoors(place). Relation settled(place).
  Relation peaceable(group). Relation routed(group).
  Relation dark().
  Relation witnessedAttack(group, group, group).
  Relation refusesService(group, group).
  Relation capable(group, capability). Relation brings(member, capability).
  Relation serves(group, group).
  Query allied(a: group, b: group) means serves(a, b) or serves(b, a) or (serves(a, ?m) and serves(b, ?m)).
  Relation unlit(place). Relation company(group).
  // A place's law: everyone in it, or anywhere within it, fights under that condition (a plane where fire burns
  // small, a temple where no blade is drawn). The law names a catalog condition.
  Kind law. Relation law(place, law).
  // A place where light dies: only sunlight shows anything there.
  Relation lightless(place).
  // One who lets another be: does not bar its way or fall on it (a toll paid, a bribe taken, recruits believed).
  Relation tolerates(group, group).
  // Someone falling on another: on the company, it starts a fight there and then.
  Relation assails(group, group).
  // Someone stopping another where they stand (a challenge, a hold-up): on the company, whatever it was doing is
  // broken off, and it must deal with them.
  Relation halts(group, group).
  // A company on the way, between where it set out and where it is going: enRoute(company, by this passage).
  Relation enRoute(group, passage).
  Query benighted(a: group) means company(a) and at(a, ?p) and not capable(a, sunlight)
    and ((unlit(?p) and not capable(a, light)) or lightless(?p)).
  Measure quantity(entity, good). Measure watch(clock). Measure encounterXp(group).
  Goal false.
  // Someone who means the company no good where it is: a long wait or a rest is broken off when one arrives.
  Query threatened(a: group) means at(a, ?p) and at(?o, ?p) and able(?o) and distinct(?o, a) and not peaceable(?o)
    and not allied(?o, a) and not tolerates(?o, a).
  Action wait(actor: group) "Wait a while" {
    Requires able(actor). Time 1.
  }
  Action wait_hour(actor: group) "Wait an hour" {
    Requires able(actor). Time 6. Interrupted when threatened(actor).
    Result "An hour passes.".
  }
  Measure untilLight(clock). Measure untilMorning(clock).
  // A die thrown each watch, 1 to 100, for what is left to chance.
  Measure dice(clock).
  Action wait_for_light(actor: group) "Wait until first light" {
    Requires able(actor) and dark(). Time untilLight(clock). Interrupted when threatened(actor).
    Result "The sky greys, then lightens. It is morning.".
  }
  Action assail(actor: group, prey: group, site: place) "Fall on {prey}" {
    Description "Someone who means harm closes and attacks.".
    Requires able(actor) and at(actor, site) and at(prey, site) and able(prey) and distinct(actor, prey)
      and not peaceable(actor) and not allied(actor, prey) and not tolerates(actor, prey) and not company(actor).
    On success { Assert assails(actor, prey). }
  }
  Action attack(actor: group, opponent: group, site: place) "Attack {opponent}" {
    Description "Once it starts it goes on until one side is down or runs, and whoever falls may not get up.".
    Requires able(actor) and able(opponent) and distinct(actor, opponent) and at(actor, site) and reaches(actor, opponent)
      and not peaceable(opponent).
    Resolve combat(opponent).
  }
}

data/rules/discovery.kyr:
Module discovery_rules "Reliable discovery and trusted reports" {
  Kind fact. Kind source.
  Relation established(fact).
  Relation reveals(source, fact).
  Relation intact(source).
  Relation noticeable(source).
  Relation destructible(source).
  Relation mayExamine(group, source).
  Relation knows(group, fact).
  Relation assumesFalse(group, fact).
  Relation trusts(group, group).
  Relation learnedFrom(group, source, fact).
  Relation toldBy(group, group, fact).
  Relation publicPlace(place).
  Relation testimony(group, source).
  Relation witnessed(group, fact).
  Relation searched(group, place).
  Goal false.
  Action examine(actor: group, witness: source, statement: fact, site: place) "Examine {witness}" {
    Requires able(actor) and at(actor, site) and at(witness, site) and not benighted(actor)
      and noticeable(witness) and intact(witness) and mayExamine(actor, witness)
      and reveals(witness, statement) and established(statement) and not learnedFrom(actor, witness, statement).
    On success {
      Assert knows(actor, statement). Retract assumesFalse(actor, statement).
      Assert learnedFrom(actor, witness, statement).
    }
  }
  Action tell(actor: group, recipient: group, statement: fact, site: place) "Tell {recipient}: {statement}" {
    Result "You explain what the evidence establishes. The listener accepts your account and sets aside a conflicting assumption; their next choices remain their own.".
    Requires able(actor) and able(recipient) and distinct(actor, recipient)
      and at(actor, site) and at(recipient, site) and trusts(recipient, actor)
      and knows(actor, statement) and established(statement) and not toldBy(recipient, actor, statement).
    On success {
      Assert knows(recipient, statement). Retract assumesFalse(recipient, statement).
      Assert toldBy(recipient, actor, statement).
    }
  }
  Action ask(actor: group, informant: group, topic: source, statement: fact, site: place) "Ask {informant} about {topic}" {
    Result "{informant} tells you what they have heard about {topic}.".
    Description "Ask about an offered topic. The speaker shares an established fact they actually know.".
    Requires able(actor) and able(informant) and distinct(actor, informant)
      and at(actor, site) and at(informant, site) and testimony(informant, topic)
      and reveals(topic, statement) and noticeable(topic)
      and knows(informant, statement) and established(statement) and not toldBy(actor, informant, statement).
    On success {
      Assert knows(actor, statement). Retract assumesFalse(actor, statement).
      Assert toldBy(actor, informant, statement).
    }
  }
  Action search(actor: group, site: place) "Search {site}" {
    Description "Go over the place: walls, floor, furniture, the backs of things. Twenty minutes, once.".
    Requires able(actor) and at(actor, site) and not benighted(actor) and not searched(actor, site).
    Time 2. Resolve rummage(actor). Interrupted when threatened(actor).
    On success { Assert searched(actor, site). }
    Result "You go over {site} carefully.".
  }
  Action destroy_source(actor: group, witness: source, site: place) "Destroy {witness}" {
    Result "You destroy this source of evidence. Existing knowledge and other sources remain.".
    Requires able(actor) and at(actor, site) and at(witness, site)
      and noticeable(witness) and intact(witness) and destructible(witness).
    On success { Retract intact(witness). }
  }
}

data/rules/dominion.kyr:
Module dominion "Who holds what, how a power stands toward a company, and how its agents go about the land" {
  Kind byway.
  Relation holds(group, place). Relation keeps(group, entity). Relation covets(group, entity).
  Relation bywayFrom(byway, place). Relation bywayTo(byway, place). Measure bywayTime(byway).
  Relation knowsWay(group, byway). Relation travelling(group, byway).
  Query keepsKind(g: group, k: itemkind) means keeps(g, ?i) and itemKind(?i, k).
  // How a power stands toward a company, kept by the power and obeyed by everyone who serves it: alarmed when
  // something has gone wrong in what it holds; admitting a company to come and go; or hostile to it on sight.
  Relation alarmed(group). Relation admits(group, group). Relation hostile(group, group).
  Rule admitted when admits(?power, ?company) and serves(?member, ?power) and not tolerates(?member, ?company)
    and not hostile(?power, ?company) { Assert tolerates(?member, ?company). }
  Rule turned when hostile(?power, ?company) and serves(?member, ?power) and tolerates(?member, ?company) {
    Retract tolerates(?member, ?company).
  }
  Rule unadmitted when hostile(?power, ?company) and admits(?power, ?company) { Retract admits(?power, ?company). }
  // Who takes a toll where: a collector standing on a road. A road nobody tolls is open; trade on it moves.
  Relation tolls(group, place).
  // Where a power buys on credit, and what it owes there.
  Relation credit(group, group). Measure owes(group, group).
  // What raiders, tithe-takers and foragers have taken from a place.
  Measure losses(place).
  // A stronghold its holder has left. A power that covets it sends the band it posts, by night, and holds it.
  Relation vacant(place). Relation posts(group, group).
  Rule seized when vacant(?site) and covets(?power, ?site) and posts(?band, ?power) and able(?power) and able(?band)
    and untilLight(clock) == 1 {
    Retract vacant(?site). Assert holds(?power, ?site). Assert at(?band, ?site).
  }
  Goal false.
  Action depart(actor: group, way: byway, origin: place, destination: place) "Set out by {way} toward {destination}" {
    Description "Someone who knows the land's old ways leaves for a distant place, and is out of sight until they arrive.".
    Requires able(actor) and knowsWay(actor, way) and at(actor, origin) and bywayFrom(way, origin)
      and bywayTo(way, destination).
    On success { Retract at(actor, origin). Assert travelling(actor, way). }
  }
  Action arrive(actor: group, way: byway, destination: place) "Come by {way} to {destination}" {
    Requires travelling(actor, way) and bywayTo(way, destination).
    Time bywayTime(way).
    On success { Retract travelling(actor, way). Assert at(actor, destination). }
  }
}

data/rules/inhabitants.kyr:
Module inhabitants "How creatures that live somewhere answer those who come into it" {
  // A creature's temperament says how it meets a company that comes where it lives. A territorial one warns, then
  // falls on whoever stays; a defensive one warns, and fights only for its lair; a proud one names a price; a savage
  // one falls on you at once; one that lies in ambush strikes unless keen eyes spot it first; an obedient one keeps
  // its post and nothing else; a wary one slinks away, and fights only when cornered in its refuge. A group of one
  // species takes its species' temperament; a place may give any group one (temper_savage, temper_proud…).
  Kind temperament.
  Entity temper_territorial: temperament "territorial". Entity temper_defensive: temperament "defensive".
  Entity temper_wary: temperament "wary". Entity temper_ambush: temperament "ambush".
  Entity temper_proud: temperament "proud".
  Entity temper_obedient: temperament "obedient". Entity temper_savage: temperament "savage".
  Relation temperament(group, temperament).
  // Where it lives and what it defends; where it goes when beaten or frightened off.
  Relation lair(group, place). Relation refuge(group, place).
  // What it does, in the place's own words: its warning, its onslaught, what makes it flinch, how it yields.
  Relation warning(group, entity). Relation onslaught(group, entity). Relation flinch(group, entity).
  Relation plea(group, entity).
  // What drives it off (sunlight, flame), and the price a proud one names.
  Relation fears(group, capability). Measure tribute(group).
  Relation warned(group, group). Relation yielded(group, group).
  // Plain words for a creature whose place gives it none, by temperament: temper_words_<temperament>_<what>.
  Entity temper_words_territorial_warning: fact "{?g} stands its ground and watches you. It will not have you here for long.".
  Entity temper_words_territorial_onslaught: fact "{?g} comes at you.".
  Entity temper_words_defensive_warning: fact "{?g} will not let you come any nearer.".
  Entity temper_words_defensive_onslaught: fact "{?g} comes at you to drive you off.".
  Entity temper_words_savage_onslaught: fact "{?g} comes at you without a sound.".
  Entity temper_words_ambush_warning: fact "Something is waiting here, and you see it before it moves: {?g}.".
  Entity temper_words_ambush_onslaught: fact "{?g} springs out at you.".
  Entity temper_words_obedient_onslaught: fact "{?g} comes at you, as it was made to.".
  Entity temper_words_wary_flinch: fact "{?g} slips away from you.".
  Entity temper_words_wary_onslaught: fact "Cornered, {?g} turns on you.".
  Entity temper_words_proud_warning: fact "{?g} looks at you as if you owed it something.".
  // Watches it waits, once it has warned, before it comes at whoever stays.
  Measure patience(group).
  Query confronts(g: group, c: group) means together(g, c) and company(c) and able(g) and not routed(g)
    and not tolerates(g, c) and not assails(g, c).

  // Fear comes first: whatever it fears, brought into its presence, drives it back to its refuge.
  Rule temper_shies when fears(?g, ?k) and company(?c) and together(?g, ?c) and capable(?c, ?k) and able(?g)
    and refuge(?g, ?r) and not at(?g, ?r) and flinch(?g, ?f) says "{?f}" {
    Assert at(?g, ?r). Retract assails(?g, ?c). Retract warned(?g, ?c).
  }
  // Beaten, it may beg; then it goes back to its refuge, and comes out again the next day.
  Rule temper_yields when routed(?g) and company(?c) and together(?g, ?c) and able(?g) and plea(?g, ?p)
    and not yielded(?g, ?c) says "{?p}" {
    Assert yielded(?g, ?c). Assert tolerates(?g, ?c). Retract assails(?g, ?c).
  }
  Rule temper_falls_back when routed(?g) and refuge(?g, ?r) and not at(?g, ?r) { Assert at(?g, ?r). }
  Rule temper_rallies when routed(?g) and refuge(?g, ?r) and at(?g, ?r) and untilLight(clock) == 1 {
    Retract routed(?g).
  }
  // A warning spent: whoever stayed is fallen on (for a defensive one, only in its lair).
  Rule temper_closes when warned(?g, ?c) and together(?g, ?c) and able(?g) and not routed(?g) and not tolerates(?g, ?c)
    and patience(?g) <= 0 and not temperament(?g, temper_defensive) and onslaught(?g, ?o) says "{?o}" {
    Assert assails(?g, ?c). Retract warned(?g, ?c).
  }
  Rule temper_defends when warned(?g, ?c) and temperament(?g, temper_defensive) and lair(?g, ?l) and at(?c, ?l)
    and at(?g, ?l) and able(?g) and not routed(?g)
    and not tolerates(?g, ?c) and patience(?g) <= 0 and onslaught(?g, ?o) says "{?o}" {
    Assert assails(?g, ?c). Retract warned(?g, ?c).
  }
  Rule temper_waits when warned(?g, ?c) and together(?g, ?c) and patience(?g) > 0 { Decrease patience(?g) by 1. }
  Rule temper_let_go when warned(?g, ?c) and not together(?g, ?c) { Retract warned(?g, ?c). }
  // The first meeting: a warning stops the company where it stands, whatever it was doing, and it must answer.
  Rule temper_warns when temperament(?g, ?t) and warnsFirst(?t) and company(?c) and confronts(?g, ?c) and not warned(?g, ?c)
    and warning(?g, ?w) says "{?w}" {
    Assert warned(?g, ?c). Assert halts(?g, ?c). Set patience(?g) to 1.
  }
  Relation warnsFirst(temperament).
  Initially Assert warnsFirst(temper_territorial). Initially Assert warnsFirst(temper_defensive).
  Initially Assert warnsFirst(temper_proud).
  Rule temper_falls_on when temperament(?g, temper_savage) and company(?c) and confronts(?g, ?c) and onslaught(?g, ?o)
    says "{?o}" {
    Assert assails(?g, ?c).
  }
  Rule temper_springs when temperament(?g, temper_ambush) and company(?c) and confronts(?g, ?c)
    and not capable(?c, perception) and not warned(?g, ?c)
    and onslaught(?g, ?o) says "{?o}" {
    Assert assails(?g, ?c).
  }
  Rule temper_spotted when temperament(?g, temper_ambush) and company(?c) and confronts(?g, ?c)
    and capable(?c, perception) and not warned(?g, ?c)
    and warning(?g, ?w) says "{?w}" {
    Assert warned(?g, ?c). Assert halts(?g, ?c). Set patience(?g) to 1.
  }
  Rule temper_keeps_post when temperament(?g, temper_obedient) and company(?c) and confronts(?g, ?c)
    and lair(?g, ?p) and at(?g, ?p)
    and onslaught(?g, ?o) says "{?o}" {
    Assert assails(?g, ?c).
  }
  Rule temper_cornered when temperament(?g, temper_wary) and company(?c) and confronts(?g, ?c)
    and refuge(?g, ?r) and at(?g, ?r)
    and onslaught(?g, ?o) says "{?o}" {
    Assert assails(?g, ?c).
  }
  Rule temper_slinks when temperament(?g, temper_wary) and company(?c) and confronts(?g, ?c)
    and refuge(?g, ?r) and not at(?g, ?r)
    and flinch(?g, ?f) says "{?f}" {
    Assert at(?g, ?r).
  }
  Goal false.
  // A proud creature's price, paid: it lets the company be.
  Action pay_tribute(actor: group, lord: group, site: place) "Give {lord} what it asks" {
    Description "A proud creature names a price for letting you pass; paid, it keeps its word.".
    Requires able(actor) and company(actor) and at(actor, site) and at(lord, site) and warned(lord, actor)
      and temperament(lord, temper_proud) and quantity(actor, gold) >= tribute(lord).
    On success {
      Decrease quantity(actor, gold) by tribute(lord). Increase quantity(lord, gold) by tribute(lord).
      Assert tolerates(lord, actor). Retract warned(lord, actor).
    }
    Result "{lord} takes it, and lets you be.".
  }
}

data/rules/needs.kyr:
Module world_needs "Food" {
  Relation eats(group). Relation hungry(group).
  Measure nextMeal(group).
  Goal false.
  Rule meal when eats(?g) and watch(clock) >= nextMeal(?g) and quantity(?g, rations) >= 1 {
    Decrease quantity(?g, rations) by 1. Increase nextMeal(?g) by 144. Retract hungry(?g).
  }
  Rule hunger when eats(?g) and watch(clock) >= nextMeal(?g) and quantity(?g, rations) < 1 and not hungry(?g) {
    Assert hungry(?g).
  }
}

data/rules/people.kyr:
Module world_people "Company and intention" {
  Relation acceptsEscort(group, group). Relation dismissed(group, group).
  // Someone taken from home: who set them free, where home is, and what their people will give whoever brings them
  // back. Brought home by a company they are home, and grateful to it, and the thanks are paid.
  Relation freedBy(group, group). Relation home(group, place). Relation cameHome(group). Relation grateful(group, group).
  Measure thanks(group).
  Rule brought_home when following(?person, ?company) and home(?person, ?place) and at(?person, ?place)
    and not cameHome(?person) {
    Retract following(?person, ?company). Assert cameHome(?person). Assert grateful(?person, ?company).
    Increase quantity(?company, gold) by thanks(?person).
  }
  Goal false.
  Action lead(actor: group, companion: group, site: place) "Ask {companion} to come with you" {
    Requires able(actor) and able(companion) and distinct(actor, companion) and at(actor, site)
      and at(companion, site) and acceptsEscort(companion, actor) and not following(companion, actor).
    On success { Assert following(companion, actor). Retract dismissed(companion, actor). }
    Result "{companion} falls in beside you.".
  }
  Action part_ways(actor: group, companion: group, site: place) "Let {companion} make their own way" {
    Requires able(actor) and able(companion) and at(actor, site) and at(companion, site)
      and acceptsEscort(companion, actor) and not dismissed(companion, actor) and not hobbled(companion).
    On success { Retract following(companion, actor). Assert dismissed(companion, actor). }
    Result "{companion} nods, and lets you go about your business.".
  }
}

data/rules/probing.kyr:
Module probing "Trying things: looking closely, prodding, prying, burning, pushing, listening" {
  Entity looking: verb "looked over closely". Entity prodding: verb "prodded with a pole".
  Entity prying: verb "pried at with a bar". Entity burning: verb "put to the flame".
  Entity pushing: verb "pushed and pulled". Entity listening: verb "listened at".
  // Anything that can be handled can be tried; what it does when tried is the author's (an observation, an event,
  // a rule on tried). A try that finds nothing says so; offering it never reveals anything.
  Initially Assert needs(prodding, pole). Initially Assert needs(prying, crowbar). Initially Assert needs(burning, flame).
  Goal false.
  Action look_closely(actor: group, target: entity, site: place) "Look closely at {target}" {
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target) and not benighted(actor)
      and not tried(target, looking).
    On success { Assert tried(target, looking). }
    Result "You look closely at {target}.".
  }
  Action prod(actor: group, target: entity, site: place) "Prod {target} with the pole" {
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target) and not benighted(actor)
      and equippedFor(actor, prodding) and not tried(target, prodding).
    On success { Assert tried(target, prodding). }
    Result "You prod {target} with the pole, from as far off as it allows.".
  }
  Action pry(actor: group, target: entity, site: place) "Pry at {target} with the bar" {
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target) and not benighted(actor)
      and equippedFor(actor, prying) and not tried(target, prying).
    On success { Assert tried(target, prying). }
    Result "You get the bar into {target} and lean on it.".
  }
  Action burn(actor: group, target: entity, site: place) "Hold a flame to {target}" {
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target)
      and equippedFor(actor, burning) and not tried(target, burning).
    On success { Assert tried(target, burning). }
    Result "You hold a flame to {target}.".
  }
  Action push(actor: group, target: entity, site: place) "Push and pull at {target}" {
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target) and not benighted(actor)
      and not tried(target, pushing).
    On success { Assert tried(target, pushing). }
    Result "You push at {target}, then pull.".
  }
  Action listen(actor: group, target: entity, site: place) "Listen at {target}" {
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target) and not benighted(actor)
      and not tried(target, listening).
    On success { Assert tried(target, listening). }
    Result "You put an ear to {target}, and hold your breath.".
  }
}

data/rules/services.kyr:
Module world_services "Lodging, goods and camping" {
  Kind service. Kind servicekind.
  Entity lodging: servicekind "Lodging". Entity healing: servicekind "Healing". Entity passage_fare: servicekind "Passage".
  Relation offers(group, service). Relation serviceOf(service, servicekind). Relation sells(group, good).
  Measure fee(service). Measure goodsPrice(group, good).
  Goal false.
  Action take_lodging(actor: group, host: group, service: service, site: place) "Take {service} from {host}" {
    Requires able(actor) and able(host) and distinct(actor, host) and at(actor, site) and at(host, site)
      and not refusesService(host, actor) and offers(host, service) and serviceOf(service, lodging) and quantity(actor, gold) >= fee(service).
    Time untilMorning(clock). Resolve recover(actor).
    On success { Decrease quantity(actor, gold) by fee(service). Increase quantity(host, gold) by fee(service).
      Retract hungry(actor). Increase nextMeal(actor) by 144. }
    Result "You eat a hot supper and sleep long in a dry bed.".
  }
  Action take_healing(actor: group, healer: group, service: service, site: place) "Ask {healer} for {service}" {
    Requires able(actor) and able(healer) and distinct(actor, healer) and at(actor, site) and at(healer, site)
      and not refusesService(healer, actor) and offers(healer, service) and serviceOf(service, healing) and quantity(actor, gold) >= fee(service).
    Time 6. Resolve recover(actor).
    On success { Decrease quantity(actor, gold) by fee(service). Increase quantity(healer, gold) by fee(service). }
    Result "{healer} cleans and dresses every wound in the company.".
  }
  Action buy_goods(actor: group, seller: group, goods: good, site: place) "Buy one {goods} from {seller}" {
    Requires able(actor) and able(seller) and distinct(actor, seller) and at(actor, site) and at(seller, site)
      and not refusesService(seller, actor) and sells(seller, goods) and quantity(seller, goods) >= 1 and quantity(actor, gold) >= goodsPrice(seller, goods).
    On success { Decrease quantity(actor, gold) by goodsPrice(seller, goods). Increase quantity(seller, gold) by goodsPrice(seller, goods).
      Decrease quantity(seller, goods) by 1. Increase quantity(actor, goods) by 1. }
    Result "{seller} counts the coins and hands over one {goods}.".
  }
  Action camp(actor: group, site: place) "Make camp at {site}" {
    Requires able(actor) and at(actor, site) and not indoors(site) and not settled(site) and not hungry(actor).
    Time untilMorning(clock). Resolve rough(actor). Interrupted when threatened(actor).
    Result "You find what shelter there is, and sleep in turns.".
  }
}

